<?php require_once __DIR__.'/../includes/student_auth_check.php';require_once __DIR__.'/../config/db.php';$rows=[];try{$q=db()->prepare('SELECT r.*,u.full_name tutor FROM reviews r JOIN tutors t ON t.id=r.tutor_id JOIN users u ON u.id=t.user_id WHERE r.student_id=? ORDER BY r.created_at DESC');$q->execute([$_SESSION['user_id']]);$rows=$q->fetchAll();}catch(Throwable $e){}$pageTitle='My reviews';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?><main class="container py-5"><h1 class="h2">My reviews</h1><?php foreach($rows as $r):?><div class="profile-section my-2"><strong><?=e($r['tutor'])?></strong><div class="rating"><?=str_repeat('★',(int)$r['rating'])?></div><?=e($r['comment'])?></div><?php endforeach;?></main><?php require __DIR__.'/../includes/footer.php';?>
